import heapq

def shortest_path(edges, start, end):
    # If start and end are the same node
    if start == end:
        return (0, [start])

    # Build adjacency list graph
    graph = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = {}
        graph[from_node][to_node] = weight

    # Check for negative weights
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight detected")

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous = {node: None for node in graph}
    previous[end] = None
    pq = [(0, start)]
    visited = set()

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        # Skip if already processed with shorter distance
        if current_node in visited or current_dist > distances.get(current_node, float('inf')):
            continue
        visited.add(current_node)

        # Early exit if we reached the destination
        if current_node == end:
            break

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node].items():
                new_dist = current_dist + weight

                # Update if shorter path found
                if new_dist < distances.get(neighbor, float('inf')):
                    distances[neighbor] = new_dist
                    previous[neighbor] = current_node
                    heapq.heappush(pq, (new_dist, neighbor))

    # If no path exists
    if distances.get(end) == float('inf') or end not in graph:
        return (None, None)

    # Reconstruct path
    path = []
    node = end
    while node is not None:
        path.append(node)
        node = previous[node]

    path.reverse()

    return (distances[end], path)
